package ledger

// Refactoring log:
//  - Replaced the hand-rolled selection sort with sort.Slice on a copy of the
//    input entries (the input slice is still never mutated).
//  - Replaced the goroutine-per-entry fan-out over a channel with a simple
//    sequential loop; the output is identical and the code is much simpler.
//  - Split the single 200-line function into small helpers: header, row,
//    date, description, and amount formatting.
//  - Validated currency, locale, and dates up front with descriptive errors
//    instead of errors.New("").
//  - Kept the original formatting semantics exactly: byte-based truncation of
//    descriptions, rune-based right-alignment of the amount column.

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if !validCurrency(currency) {
		return "", errInvalidCurrency
	}
	if !validLocale(locale) {
		return "", errInvalidLocale
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(locale))
	for _, entry := range sorted {
		line, err := formatLine(locale, currency, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

func validCurrency(currency string) bool {
	return currency == "USD" || currency == "EUR"
